const e = $json;
const sanitizeSmsText=value=>{if(value===null||value===undefined)return value;let text=String(value).replace(/\s+/g,' ');const blockTags='p|div|li|tr|table|thead|tbody|ul|ol|h[1-6]|section|article|header|footer|blockquote';text=text.replace(/<\s*br\s*\/?\s*>/gi,'\n');text=text.replace(new RegExp('<\\s*/\\s*(?:'+blockTags+')\\s*>','gi'),'\n');text=text.replace(new RegExp('<\\s*(?:'+blockTags+')(?:\\s[^>]*)?>','gi'),'\n');text=text.replace(/<[^>]*>/g,'');const entities={nbsp:' ',amp:'&',lt:'<',gt:'>',quot:'"',apos:"'",'#39':"'"};text=text.replace(/&(nbsp|amp|lt|gt|quot|apos|#39);/gi,(m,name)=>entities[name.toLowerCase()]??m);return text.replace(/[ \t\f\v]+/g,' ').replace(/ *\n */g,'\n').replace(/\n{2,}/g,'\n').replace(/ +([,.;:!?])/g,'$1').trim();};
const decision = e.decision ?? {};
const route = decision.route ?? 'GENERAL';
const i = e.intelligence ?? {};
const r = e.response?.validated ?? {};
const resolution = e.context?.resolution ?? {};
const create = resolution.create_lead === true;
const update = resolution.update_lead === true;
const name = i.customer?.name ?? e.context?.customer?.name ?? e.context?.lead?.name ?? '';
const mail = i.customer?.email ?? e.context?.customer?.email ?? e.context?.lead?.email ?? '';
const phone = e.event?.sender ?? i.customer?.phone ?? '';
const parent = e.identity?.parent_message_id ?? e.event?.message_id ?? '';
const language = decision.language ?? 'English';
const signal = i.appointment?.signal ?? 'NONE';
const requestQuery = String(e.event?.content ?? '').trim();
const bookingDate = r.booking_date == null ? '' : String(r.booking_date).trim();
const bookingTime = r.booking_time == null ? '' : String(r.booking_time).trim();
const bookingConfirmed = route === 'BOOKING' && signal === 'BOOKED' && bookingDate.length > 0 && bookingTime.length > 0;
const cancellationRequested = signal === 'CANCEL';
const customerCandidate = route === 'EMAIL_HANDOFF' ? r.email_body : r.sms_response;
const customerResponse = typeof customerCandidate === 'string' && customerCandidate.trim() ? customerCandidate : null;
const routePermitsCustomerResponse = route !== 'DND';
const sendUser = decision.send_user_response === true && decision.block_delivery !== true && routePermitsCustomerResponse && customerResponse !== null;
const managerCandidate = typeof decision.manager_sms === 'string' && decision.manager_sms.trim() ? sanitizeSmsText(decision.manager_sms.trim()) : null;
const managerRoute = route === 'DND' || route === 'ESCALATION';
const sendManager = decision.send_manager_sms === true && managerRoute && managerCandidate !== null;
let fe;
if (route === 'DND') fe = 'DND';
else if (route === 'ESCALATION' || i.escalation?.required === true || i.journey?.intent === 'Managerial Review') fe = 'Managerial Review';
else if (cancellationRequested) fe = 'Appointment Cancellation Requested';
else if (bookingConfirmed) fe = 'Appointment Booked';
else fe = create ? 'Lead' : 'Contacted';
let leadStatus = 'First Response Sent';
if (route === 'DND') leadStatus = 'DND';
else if (route === 'ESCALATION') leadStatus = 'Managerial Review';
else if (route === 'BOOKING') leadStatus = bookingConfirmed ? 'Visit Booked' : 'Visit Requested';
else if (route === 'VISIT') leadStatus = i.journey?.intent === 'Visit Booked' && !bookingConfirmed ? 'Visit Requested' : (i.journey?.intent ?? 'Visit Requested');
const response = sendUser ? customerResponse : null;
const common = { lead_status: leadStatus, lead_name: name, lead_mail: mail, lead_phone: phone, source: 'SMS', message_id: e.event?.message_id ?? '', create_lead: create, update_lead: update, sender_number: e.event?.sender ?? '', recipient_number: e.event?.recipient ?? '', user_language: language, appointment_cancellation_requested: cancellationRequested, response, request_query: requestQuery, parent_message_id: parent, fe_lead_status: fe, send_user_response: sendUser, send_manager_sms: sendManager, manager_sms: sendManager ? managerCandidate : null };
const output = { ...common };
if (!sendUser) output.Response = 'null';
if (route === 'DND' || route === 'ESCALATION' || route === 'EMAIL_HANDOFF') output.parent_id = parent;
if (route === 'ESCALATION') output.user_response = response;
if (route === 'EMAIL_HANDOFF') {
  output.request = requestQuery;
  output.response_mode = 'email';
  output.preferred_communication_mode_selected = true;
  output.preferred_communication_mode = 'email';
  output.preferred_communication_mode_old_messageID = parent;
}
if (route === 'BOOKING') {
  output.booking_status = bookingConfirmed;
  output.booking_date = bookingDate;
  output.booking_time = bookingTime;
}
return [{ json: output }];
